// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= 1e30);
        // Simulate a non-shutdown pool by setting cvxPoolInfo via owner
        // Since owner() returns address(this) in reference, we can set it
        // But we need a mock booster that returns shutdown=false
        // For simplicity, we assume the default poolInfo returns shutdown=false
        // We'll just check that if booster.poolInfo(pId).shutdown is true, depositAndStake does nothing
        // So the rule: either depositAndStake does nothing (if shutdown) or stakedBalance increases
        uint256 stakedBefore = c.stakedBalance();
        c.depositAndStake(amount);
        uint256 stakedAfter = c.stakedBalance();
        bool isShutdown = c.isCvxShutdown();
        assertTrue(isShutdown || stakedAfter >= stakedBefore);
    }
}

