import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // Transfer ownership to newOwner
        c.transferOwnership(newOwner);
        // Attempt a depositAndStake call (as operator, which is address(this) by default)
        // We won't revert on revert; we just call and check ownership afterwards
        // If pool info not set, depositAndStake may revert; we ignore that
        try c.depositAndStake(1e18) {} catch {}
        // General rule: owner() should NOT be address(0); if it is zero, the bug is triggered
        assertTrue(c.owner() == newOwner);
    }
}

