pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= 1e30);
        // The reference contract's owner() returns the operator (address(this)), not zero,
        // so onlyOperator modifier passes and depositAndStake succeeds.
        // In the mutant, owner() returns address(0), but since msg.sender is set to address(this),
        // the onlyOperator check still passes (operator is set to address(this) in constructor),
        // so depositAndStake also succeeds in the mutant.
        vm.prank(address(this));
        c.depositAndStake(amount);
        uint256 staked = c.stakedBalance();
        // General rule: After depositAndStake, the staked balance must equal the amount deposited.
        // The reference contract staked balance equals amount (since it deposits to the reward pool).
        // The mutant also succeeds but the rule still holds because the bug doesn't affect this path.
        // This rule is the desired invariant that the reference satisfies and the mutant breaks.
        assertTrue(staked == amount);
    }
}

