pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(address newOperator, uint256 amount) public {
        vm.assume(newOperator != address(0) && newOperator != address(this));
        vm.assume(amount > 0 && amount < 1e30);

        if (newOperator != address(0)) {
            c.setOperator(newOperator);
        }

        // We need to ensure depositAndStake can be called; we prank as the operator
        vm.prank(newOperator != address(0) ? newOperator : address(this));
        (bool success, ) = address(c).call(abi.encodeWithSignature("depositAndStake(uint256)", amount));

        // The general rule: The operator stored in the contract should be the one we set (or the constructor address if never changed)
        // For the reference contract, after setOperator(newOperator), operator is newOperator; for the mutant it becomes address(0)
        address expectedOperator = newOperator;
        // If setOperator was never called, the operator is the constructor argument (address(this))
        if (newOperator == address(0)) {
            expectedOperator = address(this);
        }
        address actualOperator = c.operator();
        assertTrue(actualOperator == expectedOperator, "Operator should match the one set by setOperator");
    }
}

